css:
#tongsci1-3-2-2-1-galileo .gl-body { grid-template-columns: 1060px minmax(0, 1fr); }
.gl-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #cfe6f7; }
.gl-stage canvas { touch-action: none; cursor: grab; }
.gl-panel { gap: 12px; }
.gl-out { margin: 0; font-size: 21px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 4.6em; flex: none; }
.gl-out b { color: var(--accent); }
.gl-facts { display: grid; grid-template-columns: auto 1fr; gap: 6px 12px; margin: 0; font-size: 19px; line-height: 1.4; }
.gl-facts dt { font-weight: 800; color: var(--accent); white-space: nowrap; }
.gl-facts dd { margin: 0; }
section.ex.u-done .gl-facts dt:nth-of-type(n+3), section.ex.u-done .gl-facts dd:nth-of-type(n+3) { display: none; }

